<?php
defined('ABSPATH') || exit;
function tkcq_create_form($lang){
 $et=$lang==='et';$form=WPCF7_ContactForm::get_template(['title'=>'TKC City Surprise check-in ['.strtoupper($lang).']','locale'=>$et?'et':'en_GB']);$map=get_option('tkc_page_map',[]);$privacy=!empty($map['privacy-policy'][$lang])?get_permalink($map['privacy-policy'][$lang]):get_privacy_policy_url();$mb=(int)(tkcq_upload_limit()/MB_IN_BYTES);$heic=tkcq_supports_heic();$types='jpg|jpeg|png|webp'.($heic?'|heic|heif':'');$formats=$heic?'JPG, PNG, WebP, HEIC':'JPG, PNG, WebP';
 $markup='<p><label>'.($et?'Hüüdnimi *':'Nickname *').' [text* quest-nickname maxlength:80 autocomplete:off]</label></p><p><label>'.($et?'Avastusfoto *':'Check-in photo *').' [file* quest-photo filetypes:'.$types.' limit:'.tkcq_upload_limit().']</label><small>'.($et?'Üks foto ('.$formats.'), kuni ':'One photo ('.$formats.'), up to ').$mb.' MB. '.($et?'Koht ja nõutud žest peavad olema samal fotol; nägu ei pea näitama.':'Include the location and required gesture in the same photo; no face is needed.').($heic?'':($et?' HEIC-foto ekspordi esmalt JPG-vormingusse.':' Export HEIC photos as JPG first.')).'</small></p>';
 $markup.='<p><label>'.($et?'Soovita läheduses mõnd kohta (valikuline)':'Recommend a nearby place (optional)').' [text quest-place maxlength:180]</label></p><p><label>'.($et?'Soovitatud koha aadress (valikuline)':'Recommended place address (optional)').' [text quest-address maxlength:240]</label></p><p><label>'.($et?'Kommentaar (valikuline)':'Comment / anything to share (optional)').' [textarea quest-comment maxlength:3000]</label></p><div class="tkc-honey" aria-hidden="true"><label>Leave empty [text tkc-website tabindex:-1 autocomplete:off]</label></div><p><a href="'.esc_url($privacy).'">'.($et?'Privaatsusteave':'Privacy notice').'</a></p><p>[submit "'.($et?'Saada avastusfoto':'Submit check-in').'"]</p>';
 $markup=preg_replace('/(<p><label>[^<]*\[text\* quest-nickname[^\]]*\]<\/label><\/p>)/','$1<p><label>'.($et?'E-posti aadress * (ei avaldata)':'Email * (not public)').' [email* quest-email autocomplete:email maxlength:254]</label></p>',$markup,1);
 $markup=preg_replace('/<p>\[submit /','<p>[acceptance quest-public]'.tkcq_public_disclosure($lang).'[/acceptance]</p><p>[submit ',$markup,1);
 $messages=$form->prop('messages');$messages=array_merge($messages,['mail_sent_ok'=>$et?'Sinu osalemisfoto on saadetud. Aitäh osalemast!':'Your check-in has been submitted. Thank you for taking part!','mail_sent_ng'=>$et?'Saatmine ei õnnestunud. Palun proovi uuesti.':'Your check-in could not be saved. Please try again.','validation_error'=>$et?'Palun kontrolli märgitud välju.':'Please check the highlighted fields.','invalid_required'=>$et?'Palun täida see väli.':'Please fill out this field.','upload_file_type_invalid'=>$et?'Palun vali JPG-, PNG- või WebP-foto.':'Please choose a JPG, PNG or WebP photo.','upload_file_too_large'=>$et?'Foto on liiga suur.':'The photo is too large.']);
 $email=function_exists('tkcs_public_email')?tkcs_public_email():get_option('admin_email');
 $form->set_properties(['form'=>$markup,'messages'=>$messages,'mail'=>['active'=>true,'subject'=>'City Surprise check-in','sender'=>'The Kind Circle <'.$email.'>','recipient'=>$email,'body'=>'City Surprise submissions are stored privately. This email is disabled for this form.','additional_headers'=>'','attachments'=>'','use_html'=>false,'exclude_blank'=>true],'mail_2'=>['active'=>false],'additional_settings'=>"skip_mail: on\nacceptance_as_validation: on\nflamingo_name: \"[quest-nickname]\"\nflamingo_subject: \"City Surprise check-in\""]);
 $form->save();return (int)$form->id();
}
function tkcq_setup_admin(){
 if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>City Surprise — setup and guide / 城市彩蛋使用说明</h1>';
 $forms=get_option('tkcq_forms',[]);$map=get_option('tkc_page_map',[]);$dir=tkcq_private_dir();
 if(isset($_GET['done']))echo '<div class="notice notice-success"><p>City Surprise is ready. No public task was created.</p></div>';
 echo '<h2>System status</h2><ul><li>Contact Form 7: '.(class_exists('WPCF7_ContactForm')?'ready':'not active').'</li><li>Flamingo: '.(class_exists('Flamingo_Inbound_Message')?'ready':'not active').'</li><li>Private photos outside public web root: '.(is_wp_error($dir)?esc_html($dir->get_error_message()):'ready').'</li><li>Upload limit: '.esc_html(size_format(tkcq_upload_limit())).'</li><li>Timezone: Europe/Tallinn; current time '.esc_html(wp_date('Y-m-d H:i T',time(),new DateTimeZone('Europe/Tallinn'))).'</li><li>Image processing: '.(wp_image_editor_supports(['mime_type'=>'image/jpeg'])?'JPEG ready':'unavailable').'</li><li>HEIC: '.(wp_image_editor_supports(['mime_type'=>'image/heic'])?'supported — enabled in upload forms':'not supported by the server; use JPG/PNG/WebP').'</li></ul>';
 if(empty($forms['en'])||empty($forms['et'])||empty($map['city-eggs'])){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcq_install');echo '<input type="hidden" name="action" value="tkcq_install"><p>Create two language forms, two editable listing pages and navigation links. Existing pages, events and submissions are preserved. No real or example challenge will be published.</p>';submit_button('Set up City Surprise / 建立栏目');echo '</form>';}
 else{echo '<p>';foreach(($map['activities']??$map['city-eggs'])as$lang=>$id)echo '<a class="button" href="'.esc_url(get_permalink($id)).'">'.esc_html(strtoupper($lang)).' listing</a> ';echo '<a class="button button-primary" href="'.esc_url(admin_url('post-new.php?post_type=tkc_quest')).'">Add a round / 新建一期</a></p>';}
 tkcq_layout_admin();tkcq_public_setup_box();
 echo '<h2>Weekly workflow / 每周维护</h2><ol><li>City Surprise → Add new: enter title, English mission, clue image, hint, gesture and Tallinn deadline. Fill the Estonian fields, then preview and publish.</li><li>The two public language pages read the same round automatically. Drafts and scheduled future rounds are not shown publicly.</li><li>Check-ins → choose a round: review nickname, private email, photo, recommendations, address and comment. Manage public visibility in Comments.</li><li>After the deadline, open one submission and choose “Select this participant”. Only one selection is stored per round.</li><li>In the round editor, enable “Publish selected nickname” and Update. The selected nickname announcement is separate from the public comment list. Email always remains private.</li></ol><p>截止时间由服务器在显示和接收投稿时判断，旧表单也不能逾期提交。此流程不自动发送邮件、不需要账号；邮箱必填但仅供后台查看，不收电话。</p>';
 echo '<h2>Backup and retention / 备份与保留</h2><p>Photos are outside the website public directory and may not be included in a Zone application snapshot. Include the private photo folder in your hosting backups, or download the authenticated backup below. Review and remove old submissions according to the site privacy policy; removing an entry permanently also removes its photo.</p>';
 if(class_exists('ZipArchive')){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcq_export');echo '<input type="hidden" name="action" value="tkcq_export">';submit_button('Download private check-in backup','secondary');echo '</form>';}
 echo '<h2>Private verification / 私有验收</h2><p>Verification rounds and their linked pages are private and excluded from public listings. No emails are sent. Move verification data to Trash when done.</p>';
 $test=(int)get_option('tkcq_verification_round');if($test&&get_post_status($test)==='private'){
 echo '<p><a class="button" href="'.esc_url(tkcq_url($test,'en')).'">Private EN preview</a> <a class="button" href="'.esc_url(tkcq_url($test,'et')).'">Private ET preview</a> <a class="button" href="'.esc_url(get_edit_post_link($test)).'">Edit private test round</a></p>';
 echo '<p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=tkcq_test_heic'),'tkcq_test_heic')).'">Download private HEIC test image</a></p>';
 foreach(['tkcq_expire_test'=>'Close private verification round','tkcq_trash_test'=>'Move verification data to Trash']as$action=>$label){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field($action);echo '<input type="hidden" name="action" value="'.$action.'">';submit_button($label,'secondary');echo '</form>';}
 }else{echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcq_create_test');echo '<input type="hidden" name="action" value="tkcq_create_test">';submit_button('Create private verification round','secondary');echo '</form>';}
 if(get_option('tkcq_verification_report')){echo '<h3>Runtime checks</h3><pre>'.esc_html(wp_json_encode(get_option('tkcq_verification_report'),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre>';}
 echo '</div>';
}
add_action('admin_post_tkcq_install',function(){
 if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcq_install');if(!class_exists('WPCF7_ContactForm')||!class_exists('Flamingo_Inbound_Message'))wp_die('Activate Contact Form 7 and Flamingo first.');
 $dir=tkcq_private_dir(true);if(is_wp_error($dir))wp_die(esc_html($dir->get_error_message()));
 if(!get_option('tkcq_install_backup')){update_option('tkcq_install_backup',['page_map'=>get_option('tkc_page_map',[]),'menus'=>get_option('tkc_menu_map',[]),'time'=>gmdate('c')],false);}
 $forms=get_option('tkcq_forms',[]);foreach(['en','et']as$lang)if(empty($forms[$lang])||get_post_type($forms[$lang])!=='wpcf7_contact_form'){$forms[$lang]=tkcq_create_form($lang);update_option('tkcq_forms',$forms,false);}
 $map=get_option('tkc_page_map',[]);foreach(['en','et']as$lang){$et=$lang==='et';if(!empty($map['city-eggs'][$lang])&&get_post_type($map['city-eggs'][$lang])==='page')continue;
 $title=$et?'City Surprise':'City Surprise';$intro=$et?'Avasta Tallinnat ühe vihje kaupa. Leia pildil kujutatud koht ja jäädvusta see koos nõutud žestiga. Nägu ei pea näitama.':'Explore Tallinn, one clue at a time. Find the place in the clue image and photograph it with the required gesture. No face needed.';
 $content='<!-- wp:group {"className":"tkc-page-intro tkc-section","layout":{"type":"default"}} --><div class="wp-block-group tkc-page-intro tkc-section"><!-- wp:paragraph {"className":"tkc-label"} --><p class="tkc-label">'.($et?'Avasta. Leia. Jaga.':'Explore. Find. Share.').'</p><!-- /wp:paragraph --><!-- wp:heading {"level":1} --><h1 class="wp-block-heading">'.$title.'</h1><!-- /wp:heading --><!-- wp:paragraph --><p>'.$intro.'</p><!-- /wp:paragraph --></div><!-- /wp:group --><!-- wp:group {"className":"tkc-body tkcq-list-body","layout":{"type":"default"}} --><div class="wp-block-group tkc-body tkcq-list-body"><!-- wp:shortcode -->[tkc_city_eggs]<!-- /wp:shortcode --></div><!-- /wp:group -->';
 $id=wp_insert_post(wp_slash(['post_type'=>'page','post_status'=>'publish','post_title'=>$title,'post_name'=>$et?'city-eggs-et':'city-eggs','post_content'=>$content,'comment_status'=>'closed']),true);if(is_wp_error($id))wp_die(esc_html($id->get_error_message()));$map['city-eggs'][$lang]=$id;update_option('tkc_page_map',$map,false);update_post_meta($id,'tkc_key','city-eggs');if(function_exists('pll_set_post_language'))pll_set_post_language($id,$lang);
 }if(function_exists('pll_save_post_translations'))pll_save_post_translations($map['city-eggs']);
 $menus=get_option('tkc_menu_map',[]);foreach(['en','et']as$lang){$targets=[];if(!empty($menus[$lang]))$targets[]=$menus[$lang];$footer=wp_get_nav_menu_object('TKC Footer 1 '.strtoupper($lang));if($footer)$targets[]=$footer->term_id;foreach($targets as$mid){$exists=false;foreach(wp_get_nav_menu_items($mid,['suppress_filters'=>true])?:[]as$item)if((int)$item->object_id===(int)$map['city-eggs'][$lang])$exists=true;if(!$exists)wp_update_nav_menu_item($mid,0,['menu-item-title'=>$lang==='et'?'City Surprise':'City Surprise','menu-item-object-id'=>$map['city-eggs'][$lang],'menu-item-object'=>'page','menu-item-type'=>'post_type','menu-item-status'=>'publish']);}}
 // Append editable disclosure blocks; retain the previous page contents as private rollback data.
 $privacy_backup=get_option('tkcq_privacy_backup',[]);foreach(['en','et']as$lang){$pid=$map['privacy-policy'][$lang]??0;$p=$pid?get_post($pid):null;if(!$p||strpos($p->post_content,'tkcq-privacy')!==false)continue;$privacy_backup[$pid]=$p->post_content;update_option('tkcq_privacy_backup',$privacy_backup,false);
 $text=$lang==='et'?'City Surprise’is kogume hüüdnime, osalemisfoto ning sinu vabatahtlikud kohasoovitused, aadressi ja kommentaari. Neid näevad ainult korraldajad. Avaldame üksnes väljavalitud osaleja hüüdnime, mitte tema fotot ega muid sisestatud andmeid. Osalemine ei lisa sind uudiskirja saajate hulka. Sellele kehtib eespool kirjeldatud tegevusandmete säilitamise kord.':'For City Surprise we collect your nickname, check-in photo and any optional place recommendations, address and comment. Only organisers can view these submissions. We publish only the selected participant’s nickname, not their photo or other submitted details. Taking part does not subscribe you to marketing emails. The activity-record retention policy described above applies.';
 $content=$p->post_content.'<!-- wp:heading {"anchor":"tkcq-privacy"} --><h2 class="wp-block-heading" id="tkcq-privacy">'.($lang==='et'?'City Surprise’i osalemisandmed':'City Surprise check-ins').'</h2><!-- /wp:heading --><!-- wp:paragraph --><p>'.$text.'</p><!-- /wp:paragraph -->';wp_update_post(wp_slash(['ID'=>$pid,'post_content'=>$content]));}
 update_option('tkcq_installed',gmdate('c'),false);wp_safe_redirect(admin_url('edit.php?post_type=tkc_quest&page=tkcq-setup&done=1'));exit;
});
add_action('admin_post_tkcq_create_test',function(){
 if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcq_create_test');$old=(int)get_option('tkcq_verification_round');if($old&&get_post_status($old)==='private'){wp_safe_redirect(admin_url('edit.php?post_type=tkc_quest&page=tkcq-setup'));exit;}
 $id=wp_insert_post(['post_type'=>'tkc_quest','post_status'=>'private','post_title'=>'Private verification — not a public activity','post_content'=>'This private round is only for checking photo uploads, deadline enforcement and selected-nickname display.'],true);if(is_wp_error($id))wp_die('Unable to create private verification round.');
 foreach(['_tkcq_test'=>1,'_tkcq_hint'=>'Private verification only','_tkcq_hint_et'=>'Ainult privaatne kontroll','_tkcq_gesture'=>'Private upload check','_tkcq_gesture_et'=>'Privaatne üleslaadimise kontroll','_tkcq_title_et'=>'Privaatne kontroll — mitte avalik tegevus','_tkcq_body_et'=>'See privaatne voor on mõeldud ainult üleslaadimise ja tähtaja kontrollimiseks.','_tkcq_deadline'=>time()+DAY_IN_SECONDS]as$key=>$value)update_post_meta($id,$key,$value);
 $logo=(int)get_theme_mod('custom_logo');if(!$logo){$assets=get_option('tkc_asset_map',[]);$logo=(int)($assets['logo']??0);}if($logo)set_post_thumbnail($id,$logo);tkcq_sync_pages($id);update_option('tkcq_verification_round',$id,false);
 $report=['Tallinn_winter_utc'=>gmdate('c',tkcq_deadline_parse('2026-11-07T14:00')),'Tallinn_summer_utc'=>gmdate('c',tkcq_deadline_parse('2026-07-07T14:00')),'invalid_date_rejected'=>tkcq_deadline_parse('2026-02-30T12:00')===0,'exact_deadline_closed'=>!tkcq_open($id,(int)get_post_meta($id,'_tkcq_deadline',true)),'before_deadline_open'=>tkcq_open($id,(int)get_post_meta($id,'_tkcq_deadline',true)-1),'private_storage_outside_public_root'=>!is_wp_error(tkcq_private_dir()),'photos'=>$logo?'test uses existing organisation logo':'choose an image before testing'];update_option('tkcq_verification_report',$report,false);
 wp_safe_redirect(admin_url('edit.php?post_type=tkc_quest&page=tkcq-setup'));exit;
});
add_action('admin_post_tkcq_expire_test',function(){if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcq_expire_test');$id=(int)get_option('tkcq_verification_round');if(get_post_status($id)!=='private'||!get_post_meta($id,'_tkcq_test',true))wp_die('Private verification only.');update_post_meta($id,'_tkcq_deadline',time()-60);wp_safe_redirect(admin_url('edit.php?post_type=tkc_quest&page=tkcq-setup'));exit;});
add_action('admin_post_tkcq_trash_test',function(){if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcq_trash_test');$id=(int)get_option('tkcq_verification_round');if(get_post_status($id)!=='private'||!get_post_meta($id,'_tkcq_test',true))wp_die('Private verification only.');$pages=get_post_meta($id,'_tkcq_pages',true);$entries=get_posts(['post_type'=>'flamingo_inbound','post_status'=>'publish','numberposts'=>-1,'suppress_filters'=>true,'lang'=>'','meta_key'=>'_tkcq_quest_id','meta_value'=>$id]);foreach($entries as$p)wp_trash_post($p->ID);wp_trash_post($id);foreach($pages?:[]as$pid)if(get_post_type($pid)==='page')wp_trash_post($pid);update_option('tkcq_verification_round',0,false);wp_safe_redirect(admin_url('edit.php?post_type=tkc_quest&page=tkcq-setup'));exit;});
add_action('admin_post_tkcq_export',function(){
 if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcq_export');if(!class_exists('ZipArchive'))wp_die('ZIP support unavailable.');$dir=tkcq_private_dir();if(is_wp_error($dir))wp_die('Private storage unavailable.');$path=$dir.'/backup-'.bin2hex(random_bytes(12)).'.zip';$zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::EXCL)!==true)wp_die('Unable to create backup.');$manifest=[];
 foreach(get_posts(['post_type'=>'flamingo_inbound','post_status'=>['publish','trash'],'numberposts'=>-1,'suppress_filters'=>true,'lang'=>'','meta_query'=>[['key'=>'_tkcq_quest_id','compare'=>'EXISTS']]])as$p){$photo=tkcq_photo_path($p->ID);$data=['id'=>$p->ID,'round_id'=>(int)get_post_meta($p->ID,'_tkcq_quest_id',true),'round_title'=>get_the_title((int)get_post_meta($p->ID,'_tkcq_quest_id',true)),'status'=>$p->post_status,'submitted_utc'=>get_post_time('c',true,$p)];foreach(['nickname','email','place','address','comment','language','public_consent','public_consent_at','comment_id']as$key)$data[$key]=get_post_meta($p->ID,'_tkcq_'.$key,true);if($photo){$data['photo']='photos/'.basename($photo);$zip->addFile($photo,$data['photo']);}$manifest[]=$data;}
 $zip->addFromString('check-ins.json',wp_json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE));$zip->close();nocache_headers();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="city-eggs-private-backup-'.gmdate('Y-m-d').'.zip"');header('Content-Length: '.filesize($path));readfile($path);wp_delete_file($path);exit;
});

add_action('admin_init',function(){
 if(!current_user_can('manage_options')||get_option('tkcq_heic_forms_updated_v2')||!tkcq_supports_heic()||!class_exists('WPCF7_ContactForm'))return;
 foreach(get_option('tkcq_forms',[])as$id){$f=WPCF7_ContactForm::get_instance($id);if(!$f)continue;$markup=$f->prop('form');$markup=str_replace('filetypes:jpg|jpeg|png|webp ','filetypes:jpg|jpeg|png|webp|heic|heif ',$markup);$markup=str_replace(['JPG, PNG or WebP','JPG-, PNG- või WebP-','Export HEIC photos as JPG first.','HEIC-foto ekspordi esmalt JPG-vormingusse.'],['JPG, PNG, WebP or HEIC','JPG-, PNG-, WebP- või HEIC-','',''],$markup);$messages=$f->prop('messages');$all_forms=get_option('tkcq_forms',[]);$is_et=isset($all_forms['et'])&&(int)$all_forms['et']===(int)$id;$messages['upload_file_type_invalid']=$is_et?'Palun vali JPG-, PNG-, WebP- või HEIC-foto.':'Please choose a JPG, PNG, WebP or HEIC photo.';$f->set_properties(['form'=>$markup,'messages'=>$messages]);$f->save();}
 if(get_option('tkcq_forms'))update_option('tkcq_heic_forms_updated_v2',1,false);
});

add_action('admin_post_tkcq_test_heic',function(){
 if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcq_test_heic');$id=(int)get_option('tkcq_verification_round');if(get_post_status($id)!=='private'||!get_post_meta($id,'_tkcq_test',true)||!class_exists('Imagick'))wp_die('Private verification only.');$logo=get_attached_file(get_post_thumbnail_id($id));if(!$logo||!is_file($logo))wp_die('Test image unavailable.');$dir=tkcq_private_dir();if(is_wp_error($dir))wp_die('Private storage unavailable.');$path=$dir.'/verification-'.bin2hex(random_bytes(12)).'.heic';
 try{$img=new Imagick($logo);$img->setImageFormat('HEIC');$img->writeImage($path);$img->clear();}catch(Throwable $e){wp_die('This server cannot encode a HEIC verification image.');}
 nocache_headers();header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="tkc-private-upload-test.heic"');header('Content-Length: '.filesize($path));readfile($path);wp_delete_file($path);exit;
});
